/*
 * deletion_tower_order10_20261104.c  (opus-2026-11-04-S72)
 *
 * Order-10 test of HYP-9455 (second pre-registration, P6-P8), memory-light and multithreaded (OpenMP).
 *
 * For every converse-merged tournament node of order n <= 10 it computes
 *   - the path-endpoint-weighted converse-merged deck W(T) = sum_x (h_s(x) + h_e(x)) e_[T - x] (primitive form), and
 *   - the unweighted converse-merged deck (multiset of [T - x]),
 * and tests both for injectivity.  Orders <= 9 are built and stored exactly (as in deletion_tower_census_20261104.c);
 * order 10 is generated by one-vertex extension of the 191,536 order-9 classes (98,066,432 extensions), sorted and
 * deduplicated, and its nodes are compared through 64-bit hashes of the two vectors; every group of equal hashes is
 * re-examined with the exact vectors, so the reported collision counts are exact.
 *
 * Canonical form: as in the census program (least adjacency code over orders respecting the refined partition by
 * score, 3-cycle count and iterated out-neighbour colour counts), written reentrantly for threads.
 *
 * Usage: deletion_tower_order10 [NMAX=10]
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <omp.h>

#define MAXN 10
typedef unsigned long long u64;

/* ---------------- reentrant canonical form ---------------- */
typedef struct {
    int n; const uint16_t *out;
    int cellof[MAXN], cellverts[MAXN][MAXN], cellsize[MAXN];
    int used[MAXN], pos[MAXN];
    u64 best; int have, cnt;
} CCtx;

static void canon_rec(CCtx *C, int q, u64 code) {
    int n = C->n;
    if (q == n) {
        if (!C->have || code < C->best) { C->best = code; C->have = 1; C->cnt = 1; }
        else if (code == C->best) C->cnt++;
        return;
    }
    int c = C->cellof[q];
    int nb = (q + 1) * q / 2, tot = n * (n - 1) / 2;
    for (int k = 0; k < C->cellsize[c]; k++) {
        int v = C->cellverts[c][k];
        if (C->used[v]) continue;
        u64 nc = code;
        for (int p = 0; p < q; p++) nc = (nc << 1) | ((C->out[C->pos[p]] >> v) & 1u);
        if (C->have && nc > (C->best >> (tot - nb))) continue;
        C->used[v] = 1; C->pos[q] = v;
        canon_rec(C, q + 1, nc);
        C->used[v] = 0;
    }
}

static u64 canon(int n, const uint16_t *out, int *aut) {
    CCtx C; memset(&C, 0, sizeof C);
    int col[MAXN], ncol, key[MAXN];
    for (int v = 0; v < n; v++) {
        int s = __builtin_popcount(out[v]);
        unsigned inv = (~out[v]) & ((1u << n) - 1) & ~(1u << v);
        int c3 = 0;
        for (int u = 0; u < n; u++) if ((out[v] >> u) & 1) c3 += __builtin_popcount(out[u] & inv);
        key[v] = s * 1000 + c3;
    }
    {
        int tmp[MAXN]; memcpy(tmp, key, sizeof(int) * n);
        for (int i = 1; i < n; i++) { int x = tmp[i], j = i - 1; while (j >= 0 && tmp[j] > x) { tmp[j + 1] = tmp[j]; j--; } tmp[j + 1] = x; }
        int d[MAXN], nd = 0;
        for (int i = 0; i < n; i++) if (i == 0 || tmp[i] != tmp[i - 1]) d[nd++] = tmp[i];
        for (int v = 0; v < n; v++) for (int i = 0; i < nd; i++) if (d[i] == key[v]) { col[v] = i; break; }
        ncol = nd;
    }
    for (;;) {
        int sig[MAXN][MAXN + 1];
        for (int v = 0; v < n; v++) {
            sig[v][0] = col[v];
            for (int c = 0; c < ncol; c++) sig[v][c + 1] = 0;
            for (int u = 0; u < n; u++) if ((out[v] >> u) & 1) sig[v][col[u] + 1]++;
        }
        int ord[MAXN]; for (int i = 0; i < n; i++) ord[i] = i;
        for (int i = 1; i < n; i++) {
            int x = ord[i], j = i - 1;
            while (j >= 0 && memcmp(sig[ord[j]], sig[x], sizeof(int) * (ncol + 1)) > 0) { ord[j + 1] = ord[j]; j--; }
            ord[j + 1] = x;
        }
        int ncol2 = 0, newcol[MAXN];
        for (int i = 0; i < n; i++) {
            if (i > 0 && memcmp(sig[ord[i]], sig[ord[i - 1]], sizeof(int) * (ncol + 1)) != 0) ncol2++;
            newcol[ord[i]] = ncol2;
        }
        ncol2++;
        memcpy(col, newcol, sizeof(int) * n);
        if (ncol2 == ncol) break;
        ncol = ncol2;
    }
    for (int c = 0; c < ncol; c++) C.cellsize[c] = 0;
    for (int v = 0; v < n; v++) { int c = col[v]; C.cellverts[c][C.cellsize[c]++] = v; }
    int p = 0;
    for (int c = 0; c < ncol; c++) for (int k = 0; k < C.cellsize[c]; k++) C.cellof[p++] = c;
    C.n = n; C.out = out;
    canon_rec(&C, 0, 0);
    if (aut) *aut = C.cnt;
    return C.best;
}

static void decode(int n, u64 code, uint16_t *out) {
    int tot = n * (n - 1) / 2, b = tot - 1;
    for (int i = 0; i < n; i++) out[i] = 0;
    for (int q = 1; q < n; q++) for (int p = 0; p < q; p++) {
        int bit = (code >> b) & 1; b--;
        if (bit) out[p] |= 1u << q; else out[q] |= 1u << p;
    }
}
static void converse(int n, const uint16_t *out, uint16_t *op) {
    for (int i = 0; i < n; i++) op[i] = 0;
    for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) if ((out[i] >> j) & 1) op[j] |= 1u << i;
}
static void delete_vertex(int n, const uint16_t *out, int x, uint16_t *res) {
    int k = 0;
    for (int i = 0; i < n; i++) {
        if (i == x) continue;
        uint16_t r = 0; int kk = 0;
        for (int j = 0; j < n; j++) { if (j == x) continue; if ((out[i] >> j) & 1) r |= 1u << kk; kk++; }
        res[k++] = r;
    }
}
/* dp buffer of (1<<n)*n entries supplied by caller */
static void ham_counts(int n, const uint16_t *out, u64 *hs, u64 *he, u64 *dp) {
    int full = (1 << n) - 1;
    uint16_t op[MAXN]; converse(n, out, op);
    for (int pass = 0; pass < 2; pass++) {
        const uint16_t *g = pass ? op : out;
        memset(dp, 0, sizeof(u64) * (size_t)(full + 1) * n);
        for (int v = 0; v < n; v++) dp[(size_t)(1 << v) * n + v] = 1;
        for (int S = 1; S <= full; S++) for (int v = 0; v < n; v++) {
            u64 c = dp[(size_t)S * n + v]; if (!c) continue;
            unsigned nb = g[v] & ~S;
            while (nb) { int w = __builtin_ctz(nb); nb &= nb - 1; dp[(size_t)(S | (1 << w)) * n + w] += c; }
        }
        for (int v = 0; v < n; v++) (pass ? hs : he)[v] = dp[(size_t)full * n + v];
    }
}

/* ---------------- hash map (read-only after build) ---------------- */
typedef struct { u64 *key; int *val; size_t cap; } HMap;
static void hm_init(HMap *h, size_t cap) { h->cap = cap; h->key = malloc(sizeof(u64) * cap); h->val = malloc(sizeof(int) * cap); for (size_t i = 0; i < cap; i++) h->key[i] = ~0ULL; }
static size_t hm_slot(const HMap *h, u64 k) { u64 x = k * 0x9E3779B97F4A7C15ULL; size_t i = (size_t)(x >> 17) % h->cap; while (h->key[i] != ~0ULL && h->key[i] != k) { i++; if (i == h->cap) i = 0; } return i; }
static int hm_get(const HMap *h, u64 k) { size_t i = hm_slot(h, k); return h->key[i] == k ? h->val[i] : -1; }
static void hm_put(HMap *h, u64 k, int v) { size_t i = hm_slot(h, k); h->key[i] = k; h->val[i] = v; }

typedef struct { int nclass, nmerged, nsc; u64 *code; int *mid; HMap cls; } Order;
static Order ord_[MAXN + 1];

static int cmp_u64(const void *a, const void *b) { u64 x = *(const u64 *)a, y = *(const u64 *)b; return x < y ? -1 : x > y; }

/* generate the sorted distinct canonical codes of order n from order n-1 (parallel) */
static u64 *generate(int n, int *count) {
    Order *P = &ord_[n - 1];
    size_t per = (size_t)1 << (n - 1), tot = (size_t)P->nclass * per;
    u64 *all = malloc(sizeof(u64) * (tot ? tot : 1));
    if (n == 1) { all[0] = 0; *count = 1; return all; }
#pragma omp parallel for schedule(dynamic, 16)
    for (int c = 0; c < P->nclass; c++) {
        uint16_t base[MAXN], t[MAXN];
        decode(n - 1, P->code[c], base);
        for (unsigned mask = 0; mask < per; mask++) {
            for (int i = 0; i < n - 1; i++) t[i] = base[i] | (((mask >> i) & 1) ? 0 : (1u << (n - 1)));
            t[n - 1] = (uint16_t)mask;
            all[(size_t)c * per + mask] = canon(n, t, NULL);
        }
    }
    qsort(all, tot, sizeof(u64), cmp_u64);
    size_t m = 0;
    for (size_t i = 0; i < tot; i++) if (i == 0 || all[i] != all[i - 1]) all[m++] = all[i];
    *count = (int)m;
    return realloc(all, sizeof(u64) * m);
}

static void build_small(int n) {   /* exact order with merged ids, for n <= 9 */
    Order *O = &ord_[n];
    int cnt; O->code = generate(n, &cnt); O->nclass = cnt;
    size_t cap = 4; while (cap < (size_t)cnt * 4) cap <<= 1;
    hm_init(&O->cls, cap);
    for (int i = 0; i < cnt; i++) hm_put(&O->cls, O->code[i], i);
    O->mid = malloc(sizeof(int) * cnt);
    int *conv = malloc(sizeof(int) * cnt);
#pragma omp parallel for schedule(dynamic, 64)
    for (int i = 0; i < cnt; i++) {
        uint16_t t[MAXN], op[MAXN];
        decode(n, O->code[i], t); converse(n, t, op);
        conv[i] = hm_get(&O->cls, canon(n, op, NULL));
    }
    int m = 0, sc = 0;
    for (int i = 0; i < cnt; i++) {
        if (conv[i] < 0) { fprintf(stderr, "converse missing\n"); exit(1); }
        if (conv[i] == i) sc++;
        if (conv[i] < i) O->mid[i] = O->mid[conv[i]]; else O->mid[i] = m++;
    }
    O->nmerged = m; O->nsc = sc;
    free(conv);
}

/* ---------------- node vectors ---------------- */
typedef struct { int len; int idx[MAXN]; u64 w[MAXN]; } SV;
static void sv_add(SV *s, int id, u64 w) {
    if (!w) return;
    for (int k = 0; k < s->len; k++) if (s->idx[k] == id) { s->w[k] += w; return; }
    int k = s->len++;
    while (k > 0 && s->idx[k - 1] > id) { s->idx[k] = s->idx[k - 1]; s->w[k] = s->w[k - 1]; k--; }
    s->idx[k] = id; s->w[k] = w;
}
static u64 gcdu(u64 a, u64 b) { while (b) { u64 t = a % b; a = b; b = t; } return a; }
static int sv_eq(const SV *a, const SV *b) {
    if (a->len != b->len) return 0;
    for (int k = 0; k < a->len; k++) if (a->idx[k] != b->idx[k] || a->w[k] != b->w[k]) return 0;
    return 1;
}
static u64 mix(u64 x) { x += 0x9E3779B97F4A7C15ULL; x = (x ^ (x >> 30)) * 0xBF58476D1CE4E5B9ULL; x = (x ^ (x >> 27)) * 0x94D049BB133111EBULL; return x ^ (x >> 31); }
static u64 sv_hash(const SV *s) { u64 h = mix(s->len); for (int k = 0; k < s->len; k++) h = mix(h ^ mix(((u64)s->idx[k] << 32) ^ s->w[k])); return h; }

/* primitive W and deck of a tournament of order n (lower order n-1 exact) */
static void node_vectors(int n, u64 code, SV *Wp, SV *deck, u64 *H, u64 *dp) {
    Order *P = &ord_[n - 1];
    uint16_t t[MAXN], sub[MAXN];
    u64 hs[MAXN], he[MAXN];
    decode(n, code, t);
    ham_counts(n, t, hs, he, dp);
    SV W; W.len = 0; deck->len = 0;
    u64 h = 0;
    for (int x = 0; x < n; x++) {
        h += he[x];
        delete_vertex(n, t, x, sub);
        int cls = hm_get(&P->cls, canon(n - 1, sub, NULL));
        if (cls < 0) { fprintf(stderr, "lower class missing\n"); exit(1); }
        int v = P->mid[cls];
        sv_add(&W, v, hs[x] + he[x]);
        sv_add(deck, v, 1);
    }
    u64 g = 0; for (int k = 0; k < W.len; k++) g = gcdu(g, W.w[k]);
    *Wp = W; for (int k = 0; k < Wp->len; k++) Wp->w[k] /= g;
    if (H) *H = h;
}

static void H_and_hc(int n, u64 code, u64 *H, u64 *hc);
typedef struct { u64 hw, hd, code; } Rec;
static int cmp_hw(const void *a, const void *b) { const Rec *x = a, *y = b; if (x->hw != y->hw) return x->hw < y->hw ? -1 : 1; return x->code < y->code ? -1 : x->code > y->code; }
static int cmp_hd(const void *a, const void *b) { const Rec *x = a, *y = b; if (x->hd != y->hd) return x->hd < y->hd ? -1 : 1; return x->code < y->code ? -1 : x->code > y->code; }

/* exact collision count among records with equal hash; field 0 = primitive W, 1 = deck */
static long long exact_collisions(int n, Rec *R, size_t M, int field, int printlimit) {
    qsort(R, M, sizeof(Rec), field == 0 ? cmp_hw : cmp_hd);
    long long classes = 0, printed = 0, hashgroups = 0;
    u64 *dp = malloc(sizeof(u64) * ((size_t)1 << n) * n);
    for (size_t i = 0; i < M;) {
        size_t j = i + 1;
        while (j < M && (field == 0 ? R[j].hw == R[i].hw : R[j].hd == R[i].hd)) j++;
        if (j - i > 1) {
            hashgroups++;
            size_t g = j - i;
            SV *Wv = malloc(sizeof(SV) * g), *Dv = malloc(sizeof(SV) * g); u64 *Hv = malloc(sizeof(u64) * g);
            for (size_t k = 0; k < g; k++) node_vectors(n, R[i + k].code, &Wv[k], &Dv[k], &Hv[k], dp);
            int *done = calloc(g, sizeof(int));
            for (size_t a = 0; a < g; a++) {
                if (done[a]) continue;
                int sz = 1;
                for (size_t b = a + 1; b < g; b++) if (!done[b] && (field == 0 ? sv_eq(&Wv[a], &Wv[b]) : sv_eq(&Dv[a], &Dv[b]))) { done[b] = 1; sz++; }
                if (sz > 1) {
                    classes++;
                    if (printed < printlimit) {
                        u64 Hx, hcx;
                        printf("    order %d exact %s collision class (size %d): codes", n, field == 0 ? "primitive-W" : "unweighted-deck", sz);
                        H_and_hc(n, R[i + a].code, &Hx, &hcx);
                        printf(" %llu (H=%llu, Ham. cycles=%llu)", R[i + a].code, Hx, hcx);
                        for (size_t b = a + 1; b < g; b++) if (field == 0 ? sv_eq(&Wv[a], &Wv[b]) : sv_eq(&Dv[a], &Dv[b])) { H_and_hc(n, R[i + b].code, &Hx, &hcx); printf(" %llu (H=%llu, Ham. cycles=%llu)", R[i + b].code, Hx, hcx); }
                        printf("\n");
                        printed++;
                    }
                }
            }
            free(done); free(Wv); free(Dv); free(Hv);
        }
        i = j;
    }
    free(dp);
    printf("  order %d %s: %lld hash groups of size > 1, %lld exact collision classes\n", n, field == 0 ? "primitive W" : "unweighted deck", hashgroups, classes);
    return classes;
}

/* ---------------- optional mode "full": ordinary (unmerged) decks of ordinary classes ----------------
 * For every ordinary class T of order n, the multiset of ordinary classes of T - x.  Groups of equal decks are the
 * classical non-reconstructible tournaments (McKay 2021 census: pairs at n = 3, 4, 5, 6 (four), 8 (two), none at 7,
 * then only Stockmeyer's families).  Each exact collision class is printed with the converse relation of its members. */
static void ordinary_deck(int n, u64 code, SV *deck) {
    Order *P = &ord_[n - 1];
    uint16_t t[MAXN], sub[MAXN];
    decode(n, code, t); deck->len = 0;
    for (int x = 0; x < n; x++) {
        delete_vertex(n, t, x, sub);
        int cls = hm_get(&P->cls, canon(n - 1, sub, NULL));
        if (cls < 0) { fprintf(stderr, "lower class missing\n"); exit(1); }
        sv_add(deck, cls, 1);
    }
}
/* Hamiltonian cycles (each counted once): Hamiltonian paths from vertex 0 whose end beats 0 */
static u64 ham_cycles(int n, const uint16_t *out) {
    int full = (1 << n) - 1;
    u64 *dp = calloc((size_t)(full + 1) * n, sizeof(u64));
    dp[(size_t)1 * n + 0] = 1;
    for (int S = 1; S <= full; S++) {
        if (!(S & 1)) continue;
        for (int v = 0; v < n; v++) {
            u64 c = dp[(size_t)S * n + v]; if (!c) continue;
            unsigned nb = out[v] & ~S;
            while (nb) { int w = __builtin_ctz(nb); nb &= nb - 1; dp[(size_t)(S | (1 << w)) * n + w] += c; }
        }
    }
    u64 hc = 0;
    for (int v = 1; v < n; v++) if ((out[v] >> 0) & 1) hc += dp[(size_t)full * n + v];
    free(dp);
    return hc;
}
static void H_and_hc(int n, u64 code, u64 *H, u64 *hc) {
    uint16_t t[MAXN]; decode(n, code, t);
    u64 hs[MAXN], he[MAXN];
    u64 *dp = malloc(sizeof(u64) * ((size_t)1 << n) * n);
    ham_counts(n, t, hs, he, dp); free(dp);
    u64 h = 0; for (int v = 0; v < n; v++) h += he[v];
    *H = h; *hc = ham_cycles(n, t);
}

static void full_deck_census(int n, u64 *codes, int cnt) {
    Rec *R = malloc(sizeof(Rec) * (size_t)cnt);
#pragma omp parallel for schedule(dynamic, 256)
    for (int i = 0; i < cnt; i++) { SV d; ordinary_deck(n, codes[i], &d); R[i].hd = sv_hash(&d); R[i].hw = 0; R[i].code = codes[i]; }
    qsort(R, cnt, sizeof(Rec), cmp_hd);
    int classes = 0, conv_pairs = 0, other = 0;
    for (int i = 0; i < cnt;) {
        int j = i + 1;
        while (j < cnt && R[j].hd == R[i].hd) j++;
        if (j - i > 1) {
            int g = j - i;
            SV *Dv = malloc(sizeof(SV) * g); u64 *cv = malloc(sizeof(u64) * g);
            for (int k = 0; k < g; k++) {
                ordinary_deck(n, R[i + k].code, &Dv[k]);
                uint16_t t[MAXN], op[MAXN]; decode(n, R[i + k].code, t); converse(n, t, op); cv[k] = canon(n, op, NULL);
            }
            int *done = calloc(g, sizeof(int));
            for (int a = 0; a < g; a++) {
                if (done[a]) continue;
                int mem[64], sz = 0; mem[sz++] = a;
                for (int b = a + 1; b < g; b++) if (!done[b] && sv_eq(&Dv[a], &Dv[b])) { done[b] = 1; if (sz < 64) mem[sz++] = b; }
                if (sz > 1) {
                    classes++;
                    int isconv = (sz == 2 && cv[mem[0]] == R[i + mem[1]].code);
                    if (isconv) conv_pairs++; else other++;
                    printf("    order %d same full deck (size %d):", n, sz);
                    for (int k = 0; k < sz; k++) {
                        u64 H, hc; H_and_hc(n, R[i + mem[k]].code, &H, &hc);
                        printf(" %llu%s[H=%llu, Ham. cycles=%llu]", R[i + mem[k]].code, cv[mem[k]] == R[i + mem[k]].code ? "(self-converse)" : "", H, hc);
                    }
                    printf(" -> %s\n", isconv ? "the two are converses of each other" : "NOT a converse pair");
                }
            }
            free(done); free(Dv); free(cv);
        }
        i = j;
    }
    printf("  order %d full (ordinary) deck: %d collision classes among %d classes: %d converse pairs, %d others\n", n, classes, cnt, conv_pairs, other);
    free(R);
}

int main(int argc, char **argv) {
    int NMAX = argc > 1 ? atoi(argv[1]) : 10;
    int fullmode = argc > 2 && !strcmp(argv[2], "full");
    if (NMAX > MAXN) NMAX = MAXN;
    printf("deletion_tower_order10 NMAX=%d threads=%d%s\n", NMAX, omp_get_max_threads(), fullmode ? " mode=full (ordinary decks)" : "");
    if (fullmode) {
        for (int n = 1; n <= NMAX; n++) {
            u64 *codes; int cnt;
            if (n < NMAX) { build_small(n); codes = ord_[n].code; cnt = ord_[n].nclass; }
            else codes = generate(n, &cnt);
            printf("n=%d ordinary classes=%d\n", n, cnt);
            if (n >= 3) full_deck_census(n, codes, cnt);
            fflush(stdout);
        }
        return 0;
    }
    for (int n = 1; n <= NMAX; n++) {
        double t0 = omp_get_wtime();
        if (n < NMAX) {
            build_small(n);
            Order *O = &ord_[n];
            printf("n=%d ordinary=%d self_converse=%d merged=%d\n", n, O->nclass, O->nsc, O->nmerged);
            if (n < 4) { fflush(stdout); continue; }
        }
        /* node records of order n */
        u64 *codes; int cnt;
        if (n < NMAX) { codes = ord_[n].code; cnt = ord_[n].nclass; }
        else { codes = generate(n, &cnt); printf("n=%d ordinary=%d (generated in %.1f s)\n", n, cnt, omp_get_wtime() - t0); }
        Rec *R = malloc(sizeof(Rec) * (size_t)cnt);
        char *keep = calloc(cnt, 1);
        long long nsc = 0;
#pragma omp parallel
        {
            u64 *dp = malloc(sizeof(u64) * ((size_t)1 << n) * n);
#pragma omp for schedule(dynamic, 256) reduction(+:nsc)
            for (int i = 0; i < cnt; i++) {
                uint16_t t[MAXN], op[MAXN];
                decode(n, codes[i], t); converse(n, t, op);
                u64 cv = canon(n, op, NULL);
                if (cv < codes[i]) continue;          /* the partner with the smaller code represents the node */
                if (cv == codes[i]) nsc++;
                SV Wp, D; node_vectors(n, codes[i], &Wp, &D, NULL, dp);
                R[i].hw = sv_hash(&Wp); R[i].hd = sv_hash(&D); R[i].code = codes[i];
                keep[i] = 1;
            }
            free(dp);
        }
        size_t M = 0;
        for (int i = 0; i < cnt; i++) if (keep[i]) R[M++] = R[i];
        printf("n=%d merged nodes=%zu self_converse=%lld (node vectors in %.1f s)\n", n, M, nsc, omp_get_wtime() - t0);
        exact_collisions(n, R, M, 0, 10);
        exact_collisions(n, R, M, 1, 10);
        free(R); free(keep);
        if (n == NMAX) free(codes);
        fflush(stdout);
    }
    return 0;
}
